<head>
  <meta charset="UTF-8">
  <title>잡아라!</title>
  <style>
    body { font-family: sans-serif; text-align: center; background: #fff8e1; color: #1f2937; padding: 24px; }
    button { font-size: 18px; padding: 10px 18px; margin: 4px; cursor: pointer; }
    input { font-size: 18px; padding: 8px; margin: 4px; }
  </style>
</head>
<body>
  <h1>잡아라!</h1>
  <p id="info">점수: 0 · 남은 시간: 10초</p>
  <button id="target" style="position: absolute; left: 100px; top: 160px">⭐</button>
  <script>
    let score = 0;
    let left = 10;
    const target = document.getElementById('target');
    target.addEventListener('click', function () {
      if (left <= 0) return;
      score += 1;
      target.style.left = Math.random() * 300 + 'px';
      target.style.top = 120 + Math.random() * 200 + 'px';
      update();
    });
    function update() {
      document.getElementById('info').textContent = '점수: ' + score + ' · 남은 시간: ' + left + '초';
    }
    const timer = setInterval(function () {
      left -= 1;
      update();
      if (left <= 0) {
        clearInterval(timer);
        document.getElementById('info').textContent = '끝! 점수: ' + score + '점 🎉';
      }
    }, 1000);
  </script>
</body>
</html>
