        names.push(n);
        __add("lst", n);
        document.getElementById("nm").value = '';
      }
    });
    document.getElementById("pick").addEventListener('click', function () {
      if (!names.length) {
        document.getElementById("result").textContent = '이름을 먼저 추가하세요';
      } else {
        document.getElementById("result").textContent = '당번: ' + String(listsGetRandomItem(names, false));
      }
    });

