    function sumTo(n) {
      sum = 0;
      var i_inc = 1;
      if (1 > n) {
        i_inc = -i_inc;
      }
      for (i = 1; i_inc >= 0 ? i <= n : i >= n; i += i_inc) {
        sum = (typeof sum === 'number' ? sum : 0) + i;
      }
      return sum;
    }

