      if (e.key === "ArrowLeft") {
        e.preventDefault();
        x = (typeof x === 'number' ? x : 0) + -20;
        go();
      }
    });
    document.addEventListener('keydown', function (e) {
      if (e.key === "ArrowRight") {
        e.preventDefault();
        x = (typeof x === 'number' ? x : 0) + 20;
