<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <title>팀 나누기</title>
  <style>
    body { margin: 0; padding: 24px; font-family: system-ui, "Apple SD Gothic Neo", "Noto Sans KR", sans-serif; line-height: 1.5; background: #ffffff; color: #1f2937; text-align: center; }
    button { font: inherit; font-weight: 700; padding: 10px 18px; margin: 4px; border: 0; border-radius: 10px; background: #ffc93c; color: #1c1405; cursor: pointer; }
    input { font: inherit; padding: 9px 12px; margin: 4px; border: 1px solid #9ca3af; border-radius: 9px; }
    ul { display: inline-block; text-align: left; }
    .box { display: flex; flex-direction: column; gap: 8px; padding: 12px; margin: 8px 0; border-radius: 12px; align-items: center; }
    .box.row { flex-direction: row; flex-wrap: wrap; align-items: center; justify-content: center; }
  </style>
</head>
<body>
  <h2 id="title">팀 나누기</h2>
  <div id="in" class="box row">
    <input id="nameBox" type="text" placeholder="이름">
    <button id="addBtn">추가</button>
  </div>
  <p id="people">명단: </p>
  <button id="go">팀 나누기</button>
  <div id="teamsRow" class="box row">
    <div id="boxA" class="box" style="background:#38bdf8">
      <h3 id="ta">🔵 A팀</h3>
      <ul id="listA"></ul>
    </div>
    <div id="boxB" class="box" style="background:#ec4899">
      <h3 id="tb">🔴 B팀</h3>
      <ul id="listB"></ul>
    </div>
  </div>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __add(name, value) {
      var el = $(name);
      if (el.tagName === 'UL') {
        var li = document.createElement('li');
        li.textContent = value;
        el.appendChild(li);
      } else if (el.tagName === 'INPUT') el.value += value;
      else el.textContent += value;
    }

    var names, pool, turn, who;

    function listsGetSortCompare(type, direction) {
      var compareFuncs = {
        'NUMERIC': function(a, b) {
            return Number(a) - Number(b); },
        'TEXT': function(a, b) {
            return String(a) > String(b) ? 1 : -1; },
        'IGNORE_CASE': function(a, b) {
            return String(a).toLowerCase() > String(b).toLowerCase() ? 1 : -1; },
      };
      var compare = compareFuncs[type];
      return function(a, b) { return compare(a, b) * direction; };
    }

    function listsGetRandomItem(list, remove) {
      var x = Math.floor(Math.random() * list.length);
      if (remove) {
        return list.splice(x, 1)[0];
      } else {
        return list[x];
      }
    }

    document.getElementById("addBtn").addEventListener('click', function () {
      if (!!document.getElementById("nameBox").value.trim().length) {
        names.push(document.getElementById("nameBox").value.trim());
        __add("people", String(document.getElementById("nameBox").value.trim()) + ' ');
        document.getElementById("nameBox").value = '';
      }
    });
    document.getElementById("go").addEventListener('click', function () {
      document.getElementById("listA").textContent = '';
      document.getElementById("listB").textContent = '';
      pool = names.slice().sort(listsGetSortCompare("TEXT", 1));
      turn = 0;
      while (!!pool.length) {
        who = listsGetRandomItem(pool, true);
        if (turn % 2 == 0) {
          __add("listA", who);
        } else {
          __add("listB", who);
        }
        turn = (typeof turn === 'number' ? turn : 0) + 1;
      }
    });

    names = [];
  </script>
</body>
</html>
