    .box.row { flex-direction: row; flex-wrap: wrap; align-items: center; justify-content: center; }
  </style>
</head>
<body>
  <h2 id="t">범위를 정하고 뽑아요</h2>
  <div id="range" class="box row">
    <input id="lo" type="number" placeholder="최소">
    <input id="hi" type="number" placeholder="최대">
  </div>
  <button id="pick">뽑기</button>
  <h1 id="out">?</h1>
  <ul id="hist"></ul>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __add(name, value) {
      var el = $(name);
      if (el.tagName === 'UL') {
        var li = document.createElement('li');
        li.textContent = value;
        el.appendChild(li);
      } else if (el.tagName === 'INPUT') el.value += value;
      else el.textContent += value;
    }

    var r;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    document.getElementById("pick").addEventListener('click', function () {
      if ((parseFloat(document.getElementById("lo").value) || 0) > (parseFloat(document.getElementById("hi").value) || 0)) {
        alert('최소가 최대보다 커요!');
      } else {
        r = mathRandomInt((parseFloat(document.getElementById("lo").value) || 0), (parseFloat(document.getElementById("hi").value) || 0));
        document.getElementById("out").textContent = r;
        __add("hist", r);
      }
    });
  </script>
</body>
</html>
