  </style>
</head>
<body>
  <h2 id="title">To-do List</h2>
  <div id="in" class="box row">
    <input id="task" type="text" placeholder="Task">
    <button id="addBtn">Add</button>
  </div>
  <ul id="list"></ul>
  <button id="doneBtn">Finished one ✅</button>
  <p id="stat">To do: 0 · Done: 0</p>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __add(name, value) {
      var el = $(name);
      if (el.tagName === 'UL') {
        var li = document.createElement('li');
        li.textContent = value;
        el.appendChild(li);
      } else if (el.tagName === 'INPUT') el.value += value;
      else el.textContent += value;
    }

    var all, done;

    document.getElementById("addBtn").addEventListener('click', function () {
      if (!!document.getElementById("task").value.trim().length) {
        __add("list", document.getElementById("task").value.trim());
        all = (typeof all === 'number' ? all : 0) + 1;
        document.getElementById("task").value = '';
        document.getElementById("stat").textContent = ['To do: ',all - done,' · Done: ',done].join('');
      }
    });
    document.getElementById("doneBtn").addEventListener('click', function () {
      if (done < all) {
        done = (typeof done === 'number' ? done : 0) + 1;
        document.getElementById("stat").textContent = ['To do: ',all - done,' · Done: ',done].join('');
      }
    });

    all = 0;
    done = 0;
  </script>
</body>
</html>
