    ul { display: inline-block; text-align: left; }
    .box { display: flex; flex-direction: column; gap: 8px; padding: 12px; margin: 8px 0; border-radius: 12px; align-items: center; }
    .box.row { flex-direction: row; flex-wrap: wrap; align-items: center; justify-content: center; }
  </style>
</head>
<body>
  <h1 id="title1">Nombres en orden</h1>
  <div id="row" class="box row">
    <input id="nameBox" type="text" placeholder="Escribe un nombre">
    <button id="addBtn">Añadir</button>
  </div>
  <button id="sortBtn">Ordenar</button>
  <ul id="nameList"></ul>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __add(name, value) {
      var el = $(name);
      if (el.tagName === 'UL') {
        var li = document.createElement('li');
        li.textContent = value;
        el.appendChild(li);
      } else if (el.tagName === 'INPUT') el.value += value;
      else el.textContent += value;
    }

    var names, n;

    function listsGetSortCompare(type, direction) {
      var compareFuncs = {
        'NUMERIC': function(a, b) {
            return Number(a) - Number(b); },
        'TEXT': function(a, b) {
            return String(a) > String(b) ? 1 : -1; },
        'IGNORE_CASE': function(a, b) {
            return String(a).toLowerCase() > String(b).toLowerCase() ? 1 : -1; },
      };
      var compare = compareFuncs[type];
      return function(a, b) { return compare(a, b) * direction; };
    }

    document.getElementById("addBtn").addEventListener('click', function () {
      if (!!document.getElementById("nameBox").value.length) {
        names.push(document.getElementById("nameBox").value);
        __add("nameList", document.getElementById("nameBox").value);
        document.getElementById("nameBox").value = '';
      }
    });
    document.getElementById("sortBtn").addEventListener('click', function () {
      document.getElementById("nameList").textContent = '';
      var n_list = names.slice().sort(listsGetSortCompare("IGNORE_CASE", 1));
      for (var n_index in n_list) {
        n = n_list[n_index];
        __add("nameList", n);
      }
    });

    names = [];
  </script>
</body>
</html>

