    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __pen(name) { return $(name).getContext('2d'); }
    function __clear(name) { var c = $(name); __pen(name).clearRect(0, 0, c.width, c.height); }
    function __rect(name, x, y, w, h, color) { var g = __pen(name); g.fillStyle = color; g.fillRect(x, y, w, h); }

    var x, y;

    // 이 함수를 설명하세요...
    function drawBox() {
      __clear("cv");
      __rect("cv", x, y, 30, 30, "#ef4444");
    }

    document.addEventListener('keydown', function (e) {
      if (e.key === "ArrowLeft") {
        e.preventDefault();
        x = Math.min(Math.max(x - 10, 0), 270);
        drawBox();
      }
    });
    document.addEventListener('keydown', function (e) {
      if (e.key === "ArrowRight") {
        e.preventDefault();
        x = Math.min(Math.max(x + 10, 0), 270);
        drawBox();
      }
    });
    document.addEventListener('keydown', function (e) {
      if (e.key === "ArrowUp") {
        e.preventDefault();
        y = Math.min(Math.max(y - 10, 0), 270);
        drawBox();
      }
    });
    document.addEventListener('keydown', function (e) {
      if (e.key === "ArrowDown") {
        e.preventDefault();
        y = Math.min(Math.max(y + 10, 0), 270);
        drawBox();
      }
    });

    x = 135;
    y = 135;
    drawBox();
  </script>
</body>
</html>
