  <button id="atk">공격 ⚔️</button>
  <h3 id="msg"></h3>
  <script>
    var m, p;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    document.getElementById("atk").addEventListener('click', function () {
      if (m > 0 && p > 0) {
        m = (typeof m === 'number' ? m : 0) + (0 - mathRandomInt(5, 12));
        p = (typeof p === 'number' ? p : 0) + (0 - mathRandomInt(2, 8));
        document.getElementById("mhp").textContent = '몬스터 HP: ' + String(Math.min(Math.max(m, 0), 50));
        document.getElementById("php").textContent = '내 HP: ' + String(Math.min(Math.max(p, 0), 30));
        if (m <= 0) {
          document.getElementById("msg").textContent = '🎉 몬스터를 물리쳤다!';
        } else if (p <= 0) {
          document.getElementById("msg").textContent = '💀 쓰러졌다...';
        }
      }
    });

    m = 50;
    p = 30;
  </script>
