  <h2 id="scoreLbl">점수: 0</h2>
  <h3 id="timeLbl">남은 시간: 20</h3>
  <button id="target">🎯</button>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __move(name, x, y) {
      var s = $(name).style;
      s.position = 'absolute';
      s.left = x + 'px';
      s.top = y + 'px';
    }
    function __show(name, mode) {
      var el = $(name);
      if (mode === 'toggle') mode = el.style.display === 'none' ? 'show' : 'hide';
      el.style.display = mode === 'hide' ? 'none' : '';
    }
    var __timers = [];

    var score, left;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    document.getElementById("target").addEventListener('click', function () {
      score = (typeof score === 'number' ? score : 0) + 1;
      document.getElementById("scoreLbl").textContent = '점수: ' + String(score);
      __move("target", mathRandomInt(20, 300), mathRandomInt(120, 400));
    });
    __timers.push(setInterval(function () {
      left = (typeof left === 'number' ? left : 0) + -1;
      document.getElementById("timeLbl").textContent = '남은 시간: ' + String(left);
      if (left == 0) {
        __timers.forEach(clearInterval);
        __show("target", "hide");
        document.getElementById("timeLbl").textContent = '시간 끝!';
      }
    }, 1000));

    score = 0;
    left = 20;
  </script>
</body>
</html>

