    function __size(name, prop, v) {
      var s = $(name).style;
      if (prop === 'opacity') s.opacity = v / 100;
      else if (prop === 'rotate') s.transform = 'rotate(' + v + 'deg)';
      else s[prop] = v + 'px';
    }

    var a, s;

    document.addEventListener('keydown', function (e) {
      if (e.key === "ArrowLeft") {
        e.preventDefault();
        a = (typeof a === 'number' ? a : 0) + -15;
        __size("star", "rotate", a);
      }
    });
    document.addEventListener('keydown', function (e) {
      if (e.key === "ArrowRight") {
        e.preventDefault();
        a = (typeof a === 'number' ? a : 0) + 15;
        __size("star", "rotate", a);
      }
    });
    document.addEventListener('keydown', function (e) {
      if (e.key === "ArrowUp") {
        e.preventDefault();
        s = (typeof s === 'number' ? s : 0) + 8;
        __size("star", "fontSize", s);
