  <h2 id="title">오늘 한 일</h2>
  <h1 id="num">0</h1>
  <div id="row" class="box row">
    <button id="plus">+1</button>
    <button id="zero">0으로</button>
  </div>
  <script>
    var __mem = {};
    function __save(k, v) {
      k = 'ffb:' + k;
      __mem[k] = v;
      try { localStorage.setItem(k, JSON.stringify(v)); } catch (e) {}
    }
    function __load(k, d) {
      k = 'ffb:' + k;
      try {
        var s = localStorage.getItem(k);
        if (s !== null) return JSON.parse(s);
      } catch (e) {}
      return k in __mem ? __mem[k] : d;
    }

    var done;

    document.getElementById("plus").addEventListener('click', function () {
      done = (typeof done === 'number' ? done : 0) + 1;
      __save('done', done);
      document.getElementById("num").textContent = done;
    });
    document.getElementById("zero").addEventListener('click', function () {
      done = 0;
      __save('done', 0);
      document.getElementById("num").textContent = 0;
    });

    done = __load('done', 0);
    document.getElementById("num").textContent = done;
  </script>
</body>
</html>
