  <ul id="할일목록"></ul>
  <p id="안내"></p>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __add(name, value) {
      var el = $(name);
      if (el.tagName === 'UL') {
        var li = document.createElement('li');
        li.textContent = value;
        el.appendChild(li);
      } else if (el.tagName === 'INPUT') el.value += value;
      else el.textContent += value;
    }

    var 개수;

    document.getElementById("추가버튼").addEventListener('click', function () {
      if (!!document.getElementById("할일칸").value.length) {
        __add("할일목록", document.getElementById("할일칸").value);
        개수 = (typeof 개수 === 'number' ? 개수 : 0) + 1;
        document.getElementById("할일칸").value = '';
        document.getElementById("안내").textContent = ['할 일 ',개수,'개'].join('');
      }
    });

    개수 = 0;
  </script>
</body>
</html>
