    .box.row { flex-direction: row; flex-wrap: wrap; align-items: center; justify-content: center; }
  </style>
</head>
<body>
  <h1 id="card"></h1>
  <div id="r" class="box row">
    <button id="hi">⬆️ 높다</button>
    <button id="lo">⬇️ 낮다</button>
  </div>
  <p id="res"></p>
  <p id="st">연속: 0 · 최고: 0</p>
  <script>
    var up, cur, nx, run, best;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    // 이 함수를 설명하세요...
    function guess(up) {
      nx = mathRandomInt(1, 10);
      if (nx > cur == up) {
        run = (typeof run === 'number' ? run : 0) + 1;
        document.getElementById("res").textContent = '맞았어요! ⭕';
      } else {
        run = 0;
        document.getElementById("res").textContent = '틀렸어요 ❌';
      }
      if (run > best) {
        best = run;
      }
      cur = nx;
      document.getElementById("card").textContent = cur;
      document.getElementById("st").textContent = ['연속: ',run,' · 최고: ',best].join('');
    }

    document.getElementById("hi").addEventListener('click', function () {
      guess(true);
    });
    document.getElementById("lo").addEventListener('click', function () {
      guess(false);
    });

    cur = mathRandomInt(1, 10);
    run = 0;
    best = 0;
    document.getElementById("card").textContent = cur;
  </script>
</body>
</html>
