    });
    document.addEventListener('keydown', function (e) {
      if (e.key === "ArrowUp") {
        e.preventDefault();
        __nudge("로켓", 0, -15);
        __stay("로켓");
      }
    });
    document.addEventListener('keydown', function (e) {
      if (e.key === "ArrowDown") {
        e.preventDefault();
        __nudge("로켓", 0, 15);
        __stay("로켓");
      }
    });

    __move("로켓", 60, 160);
    __follow("별", "soft");
  </script>
