<body>
  <h1 id="gsTitle">Guess the Number</h1>
  <p id="gsHint">Guess a number from 1 to 100</p>
  <div id="gsRow" class="box row">
    <input id="gsIn" type="number" placeholder="?">
    <button id="gsBtn">Check</button>
  </div>
  <h2 id="gsMsg"></h2>
  <script>
    var secret, tries;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    document.getElementById("gsBtn").addEventListener('click', function () {
      tries = (typeof tries === 'number' ? tries : 0) + 1;
      if ((parseFloat(document.getElementById("gsIn").value) || 0) == secret) {
        document.getElementById("gsMsg").textContent = ['Correct! You needed ',tries,' tries 🎉'].join('');
      } else if ((parseFloat(document.getElementById("gsIn").value) || 0) < secret) {
        document.getElementById("gsMsg").textContent = 'Higher ⬆️';
      } else {
        document.getElementById("gsMsg").textContent = 'Lower ⬇️';
      }
    });

    secret = mathRandomInt(1, 100);
    tries = 0;
  </script>
</body>
