  <input id="ansIn" type="number" placeholder="Die Zahl">
  <button id="checkBtn">Prüfen</button>
  <h2 id="result"></h2>
  <script>
    var num;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    document.getElementById("showBtn").addEventListener('click', function () {
      num = mathRandomInt(1000, 9999);
      document.getElementById("numTx").textContent = num;
      document.getElementById("result").textContent = '';
      document.getElementById("ansIn").value = '';
      setTimeout(function () {
        document.getElementById("numTx").textContent = '❓';
      }, (3) * 1000);
    });
    document.getElementById("checkBtn").addEventListener('click', function () {
      if ((parseFloat(document.getElementById("ansIn").value) || 0) == num) {
        document.getElementById("result").textContent = 'Richtig! Super Gedächtnis 🧠';
      } else {
        document.getElementById("result").textContent = 'Falsch. Es war ' + String(num);
      }
    });

    num = 0;
  </script>
</body>
