      last = pick;
      document.getElementById("idea").textContent = pick;
      n = (typeof n === 'number' ? n : 0) + 1;
      document.getElementById("seen").textContent = 'Ideas seen: ' + String(n);
    });

    ideas = ['Read a book', 'Go for a walk', 'Draw a cat', 'Bake cookies', 'Call a friend'];
