    ul { display: inline-block; text-align: left; }
  </style>
</head>
<body>
  <h1 id="t">Bubble sort steps</h1>
  <p id="st">Start: 5, 3, 8, 1, 4</p>
  <button id="go">Sort it!</button>
  <ul id="steps"></ul>
  <h2 id="done"></h2>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __add(name, value) {
      var el = $(name);
      if (el.tagName === 'UL') {
        var li = document.createElement('li');
        li.textContent = value;
        el.appendChild(li);
      } else if (el.tagName === 'INPUT') el.value += value;
      else el.textContent += value;
    }

    var a, i, j, tmp;

    document.getElementById("go").addEventListener('click', function () {
      document.getElementById("steps").textContent = '';
      a = [5, 3, 8, 1, 4];
      for (i = 1; i <= 4; i++) {
        var j_end = 5 - i;
        var j_inc = 1;
        if (1 > j_end) {
          j_inc = -j_inc;
        }
        for (j = 1; j_inc >= 0 ? j <= j_end : j >= j_end; j += j_inc) {
          if (a[(j - 1)] > a[((j + 1) - 1)]) {
            tmp = a[(j - 1)];
            a[(j - 1)] = a[((j + 1) - 1)];
            a[((j + 1) - 1)] = tmp;
            __add("steps", ['Swap ',tmp,' and ',a[(j - 1)],' → ',a].join(''));
          }
        }
      }
      document.getElementById("done").textContent = 'Sorted: ' + String(a);
    });
  </script>
</body>
</html>
