  </div>
  <h1 id="res"></h1>
  <h3 id="scoreT">맞힘 0</h3>
  <script>
    var pick, win, k;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    // 이 함수를 설명하세요...
    function play(pick) {
      k = mathRandomInt(1, 10);
      if (k % 2 == pick) {
        win = (typeof win === 'number' ? win : 0) + 1;
        document.getElementById("res").textContent = String(k) + ' 나옴! 맞혔다 🎉';
      } else {
        document.getElementById("res").textContent = String(k) + ' 나옴... 아쉽다';
      }
      document.getElementById("scoreT").textContent = '맞힘 ' + String(win);
    }

    document.getElementById("odd").addEventListener('click', function () {
      play(1);
    });
    document.getElementById("even").addEventListener('click', function () {
      play(0);
    });

    win = 0;
  </script>
</body>
