    <button id="plus">+1점</button>
    <button id="minus">-1점</button>
  </div>
  <p id="hint">10점이 되면 축하해 줘요!</p>
  <script>
    var __audio;
    function __beep(freq, sec) {
      __audio = __audio || new (window.AudioContext || window.webkitAudioContext)();
      var o = __audio.createOscillator(), g = __audio.createGain(), t = __audio.currentTime;
      o.frequency.value = freq;
      o.connect(g); g.connect(__audio.destination);
      g.gain.setValueAtTime(0.2, t);
      g.gain.exponentialRampToValueAtTime(0.001, t + sec);
      o.start(t); o.stop(t + sec);
    }

    var score;

    // 이 함수를 설명하세요...
    function paint() {
      if (score > 5) {
        document.getElementById("scoreText").style.color = "#22c55e";
      } else {
        document.getElementById("scoreText").style.color = "#111111";
      }
    }

    document.getElementById("plus").addEventListener('click', function () {
      score = (typeof score === 'number' ? score : 0) + 1;
      document.getElementById("scoreText").textContent = String(score) + '점';
      if (score == 10) {
        __beep(523.25, 0.5);
        alert('🎉 축하해요! 10점을 모았어요!');
        score = 0;
        document.getElementById("scoreText").textContent = '0점';
      }
      paint();
    });
    document.getElementById("minus").addEventListener('click', function () {
      if (score > 0) {
        score = (typeof score === 'number' ? score : 0) + -1;
      }
      document.getElementById("scoreText").textContent = String(score) + '점';
      paint();
    });

    score = 0;
  </script>
</body>
