<head>
  <meta charset="UTF-8">
  <title>Dice Duel</title>
  <style>
    body { margin: 0; padding: 24px; font-family: system-ui, "Apple SD Gothic Neo", "Noto Sans KR", sans-serif; line-height: 1.5; background: #dcfce7; color: #1f2937; text-align: center; }
    button { font: inherit; font-weight: 700; padding: 10px 18px; margin: 4px; border: 0; border-radius: 10px; background: #ffc93c; color: #1c1405; cursor: pointer; }
  </style>
</head>
<body>
  <h1 id="title">Dice Duel</h1>
  <h2 id="meTx">Me: -</h2>
  <h2 id="comTx">Computer: -</h2>
  <button id="rollBtn">Roll</button>
  <h2 id="result"></h2>
  <script>
    var me, com;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    document.getElementById("rollBtn").addEventListener('click', function () {
      me = mathRandomInt(1, 6);
      com = mathRandomInt(1, 6);
      document.getElementById("meTx").textContent = 'Me: ' + String(me);
      document.getElementById("comTx").textContent = 'Computer: ' + String(com);
      if (me > com) {
        document.getElementById("result").textContent = 'I win! 🎉';
      } else if (me < com) {
        document.getElementById("result").textContent = 'Computer wins 🤖';
      } else {
        document.getElementById("result").textContent = 'Tie!';
      }
    });
