      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __add(name, value) {
      var el = $(name);
      if (el.tagName === 'UL') {
        var li = document.createElement('li');
        li.textContent = value;
        el.appendChild(li);
      } else if (el.tagName === 'INPUT') el.value += value;
      else el.textContent += value;
    }

    var n;

    document.getElementById("addBtn").addEventListener('click', function () {
      if (!!document.getElementById("itemBox").value.trim().length) {
        n = (typeof n === 'number' ? n : 0) + 1;
        __add("items", [n,'. ',document.getElementById("itemBox").value].join(''));
        document.getElementById("total").textContent = ['Total: ',n,' items'].join('');
        document.getElementById("itemBox").value = '';
      }
    });

    n = 0;
  </script>
</body>
</html>
