        all = (typeof all === 'number' ? all : 0) + 1;
        document.getElementById("task").value = '';
        document.getElementById("stat").textContent = ['Pendientes: ',all - done,' · Hechas: ',done].join('');
      }
    });
    document.getElementById("doneBtn").addEventListener('click', function () {
      if (done < all) {
        done = (typeof done === 'number' ? done : 0) + 1;
        document.getElementById("stat").textContent = ['Pendientes: ',all - done,' · Hechas: ',done].join('');
