    .box { display: flex; flex-direction: column; gap: 8px; padding: 12px; margin: 8px 0; border-radius: 12px; align-items: center; }
    .box.row { flex-direction: row; flex-wrap: wrap; align-items: center; justify-content: center; }
  </style>
</head>
<body>
  <h1 id="title">업다운 게임</h1>
  <p id="range"></p>
  <div id="in" class="box row">
    <input id="g" type="number" placeholder="숫자">
    <button id="go">확인</button>
  </div>
  <h2 id="msg"></h2>
  <p id="left"></p>
  <button id="newBtn">새 게임</button>
  <script>
    var __audio;
    function __beep(freq, sec) {
      __audio = __audio || new (window.AudioContext || window.webkitAudioContext)();
      var o = __audio.createOscillator(), g = __audio.createGain(), t = __audio.currentTime;
      o.frequency.value = freq;
      o.connect(g); g.connect(__audio.destination);
      g.gain.setValueAtTime(0.2, t);
      g.gain.exponentialRampToValueAtTime(0.001, t + sec);
      o.start(t); o.stop(t + sec);
    }

    var ans, lo, x, hi, over, tries;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    // 이 함수를 설명하세요...
    function newGame() {
      ans = mathRandomInt(1, 500);
      lo = 1;
      hi = 500;
      tries = 10;
      over = false;
      document.getElementById("msg").textContent = '';
      document.getElementById("range").textContent = ['범위: ',lo,' ~ ',hi].join('');
      document.getElementById("left").textContent = '남은 기회: ' + String(tries);
    }

    document.getElementById("newBtn").addEventListener('click', function () {
      newGame();
    });
    document.getElementById("go").addEventListener('click', function () {
      if (!over) {
        x = (parseFloat(document.getElementById("g").value) || 0);
        tries = (typeof tries === 'number' ? tries : 0) + -1;
        if (x == ans) {
          over = true;
          document.getElementById("msg").textContent = '🎉 정답! ' + String(ans);
          __beep(523.25, 0.4);
        } else if (x < ans) {
          document.getElementById("msg").textContent = '업! ⬆️';
          lo = Math.min(Math.max(x + 1, lo), hi);
        } else {
          document.getElementById("msg").textContent = '다운! ⬇️';
          hi = Math.min(Math.max(x - 1, lo), hi);
        }
        if (!over && tries <= 0) {
          over = true;
          document.getElementById("msg").textContent = '기회 끝! 정답은 ' + String(ans);
        }
        document.getElementById("range").textContent = ['범위: ',lo,' ~ ',hi].join('');
        document.getElementById("left").textContent = '남은 기회: ' + String(tries);
        document.getElementById("g").value = '';
      }
    });

    newGame();
  </script>
</body>
</html>
