  <meta charset="UTF-8">
  <title>타자 연습</title>
  <style>
    body { margin: 0; padding: 24px; font-family: system-ui, "Apple SD Gothic Neo", "Noto Sans KR", sans-serif; line-height: 1.5; background: #dcfce7; color: #1f2937; text-align: center; }
    input { font: inherit; padding: 9px 12px; margin: 4px; border: 1px solid #9ca3af; border-radius: 9px; }
  </style>
</head>
<body>
  <h1 id="word"></h1>
  <input id="typeBox" type="text" placeholder="여기에 치고 엔터">
  <h3 id="msg"></h3>
  <p id="scoreText">점수: 0</p>
  <script>
    var words, score;

    function listsGetRandomItem(list, remove) {
      var x = Math.floor(Math.random() * list.length);
      if (remove) {
        return list.splice(x, 1)[0];
      } else {
        return list[x];
      }
    }

    // 이 함수를 설명하세요...
    function nextWord() {
      document.getElementById("word").textContent = listsGetRandomItem(words, false);
      document.getElementById("typeBox").value = '';
    }

    document.addEventListener('keydown', function (e) {
      if (e.key === "Enter") {
        e.preventDefault();
        if (document.getElementById("typeBox").value == document.getElementById("word").textContent) {
          score = (typeof score === 'number' ? score : 0) + 1;
          document.getElementById("scoreText").textContent = '점수: ' + String(score);
          document.getElementById("msg").textContent = '맞았어요!';
          document.getElementById("msg").style.color = "#22c55e";
          nextWord();
        } else {
          document.getElementById("msg").textContent = '다시!';
          document.getElementById("msg").style.color = "#ef4444";
        }
      }
    });

    words = ['사과', '바나나', '포도', '수박', '딸기'];
    score = 0;
    nextWord();
  </script>
</body>
</html>
