    var words, front, i, means;

    // 이 함수를 설명하세요...
    function show() {
      document.getElementById("card").textContent = words[(i - 1)];
      front = true;
      document.getElementById("pos").textContent = [i,' / ',words.length].join('');
    }

    document.getElementById("flip").addEventListener('click', function () {
      front = !front;
      if (front) {
        document.getElementById("card").textContent = words[(i - 1)];
      } else {
        document.getElementById("card").textContent = means[(i - 1)];
      }
    });
    document.getElementById("next").addEventListener('click', function () {
      i = (typeof i === 'number' ? i : 0) + 1;
      if (i > words.length) {
        i = 1;
      }
      show();
    });

    words = ['apple', 'school', 'friend', 'happy'];
    means = ['사과', '학교', '친구', '행복한'];
    i = 1;
    show();
  </script>
