    .box.row { flex-direction: row; flex-wrap: wrap; align-items: center; justify-content: center; }
  </style>
</head>
<body>
  <h2 id="title">📝 할 일 목록</h2>
  <div id="inputRow" class="box row">
    <input id="task" type="text" placeholder="할 일을 써요">
    <button id="add">추가</button>
  </div>
  <p id="info">할 일 0개</p>
  <ul id="todos"></ul>
  <button id="clear">모두 지우기</button>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __add(name, value) {
      var el = $(name);
      if (el.tagName === 'UL') {
        var li = document.createElement('li');
        li.textContent = value;
        el.appendChild(li);
      } else if (el.tagName === 'INPUT') el.value += value;
      else el.textContent += value;
    }

    var count;

    document.getElementById("add").addEventListener('click', function () {
      if (!!document.getElementById("task").value.trim().length) {
        __add("todos", document.getElementById("task").value);
        count = (typeof count === 'number' ? count : 0) + 1;
        document.getElementById("info").textContent = ['할 일 ',count,'개'].join('');
        document.getElementById("task").value = '';
      } else {
        document.getElementById("info").textContent = '할 일을 먼저 써 주세요';
      }
    });
    document.getElementById("clear").addEventListener('click', function () {
      document.getElementById("todos").textContent = '';
      count = 0;
      document.getElementById("info").textContent = '할 일 0개';
    });

    count = 0;
  </script>
</body>
</html>
