<body>
  <h1 id="title">What's for dinner?</h1>
  <button id="idea">Give me an idea</button>
  <h2 id="meal"></h2>
  <script>
    var last, m;

    function listsGetRandomItem(list, remove) {
      var x = Math.floor(Math.random() * list.length);
      if (remove) {
        return list.splice(x, 1)[0];
      } else {
        return list[x];
      }
    }

    document.getElementById("idea").addEventListener('click', function () {
      m = last;
      while (m == last) {
        m = listsGetRandomItem(['Tacos', 'Spaghetti', 'Fried rice', 'Pizza', 'Curry', 'Burgers'], false);
      }
      last = m;
      document.getElementById("meal").textContent = m;
    });

    last = '';
  </script>
