  </style>
</head>
<body>
  <h2 id="title">무궁화 꽃이 피었습니다</h2>
  <h1 id="light">-</h1>
  <p id="dist">거리: 0 / 20</p>
  <button id="startBtn">시작</button>
  <button id="step">앞으로 한 걸음</button>
  <h3 id="msg"></h3>
  <script>
    var __timers = [];
    var __audio;
    function __beep(freq, sec) {
      __audio = __audio || new (window.AudioContext || window.webkitAudioContext)();
      var o = __audio.createOscillator(), g = __audio.createGain(), t = __audio.currentTime;
      o.frequency.value = freq;
      o.connect(g); g.connect(__audio.destination);
      g.gain.setValueAtTime(0.2, t);
      g.gain.exponentialRampToValueAtTime(0.001, t + sec);
      o.start(t); o.stop(t + sec);
    }

    var green, pos, playing;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    document.getElementById("startBtn").addEventListener('click', function () {
      pos = 0;
      playing = true;
      green = true;
      document.getElementById("light").textContent = '🟢 움직여!';
      document.getElementById("msg").textContent = '';
      document.getElementById("dist").textContent = '거리: 0 / 20';
    });
    document.getElementById("step").addEventListener('click', function () {
      if (playing) {
        if (green) {
          pos = (typeof pos === 'number' ? pos : 0) + 1;
          document.getElementById("dist").textContent = ['거리: ',pos,' / 20'].join('');
          if (pos >= 20) {
            playing = false;
            document.getElementById("msg").textContent = '🏁 도착! 성공';
            __beep(523.25, 0.5);
          }
        } else {
          pos = 0;
          document.getElementById("dist").textContent = '거리: 0 / 20';
          document.getElementById("msg").textContent = '걸렸다! 처음부터';
          __beep(261.63, 0.4);
        }
      }
    });
    __timers.push(setInterval(function () {
      if (playing) {
        green = mathRandomInt(1, 3) > 1;
        if (green) {
          document.getElementById("light").textContent = '🟢 움직여!';
          document.getElementById("light").style.background = "#22c55e";
        } else {
          document.getElementById("light").textContent = '🔴 멈춰!';
          document.getElementById("light").style.background = "#ef4444";
        }
      }
    }, 1500));

    green = false;
    pos = 0;
    playing = false;
  </script>
</body>
