    document.getElementById("pw").addEventListener('input', function () {
      score = 0;
      d = 0;
      s = 0;
      if (document.getElementById("pw").value.length >= 8) {
        score = 1;
      }
      var i_end = document.getElementById("pw").value.length;
      var i_inc = 1;
      if (1 > i_end) {
        i_inc = -i_inc;
      }
      for (i = 1; i_inc >= 0 ? i <= i_end : i >= i_end; i += i_inc) {
        if ('0123456789'.indexOf(document.getElementById("pw").value.charAt((i - 1))) + 1 > 0) {
          d = 1;
        }
        if ('!@#$'.indexOf(document.getElementById("pw").value.charAt((i - 1))) + 1 > 0) {
          s = 1;
        }
      }
      score = score + d + s;
      if (!document.getElementById("pw").value.length) {
        document.getElementById("res").textContent = '';
      } else if (score <= 1) {
        document.getElementById("res").textContent = '약함 😟';
