          document.getElementById("final").textContent = w > l ? '🏆 최종 승리!' : (w < l ? '😭 최종 패배' : '무승부!');
          __show("again", "show");
        }
      }
    }

    document.getElementById("b1").addEventListener('click', function () {
      play(1);
