    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __move(name, x, y) {
      var s = $(name).style;
      s.position = 'absolute';
      s.left = x + 'px';
      s.top = y + 'px';
    }
    function __nudge(name, dx, dy) {
      var el = $(name), s = el.style;
      if (s.position !== 'absolute') {
        var r = el.getBoundingClientRect();
        s.position = 'absolute';
        s.left = (r.left + window.pageXOffset) + 'px';
        s.top = (r.top + window.pageYOffset) + 'px';
      }
      s.left = ((parseFloat(s.left) || 0) + dx) + 'px';
      s.top = ((parseFloat(s.top) || 0) + dy) + 'px';
    }
    function __stay(name) {
      var el = $(name), s = el.style, d = document.documentElement;
      if (s.position !== 'absolute') return;
      var x = Math.max(0, Math.min(parseFloat(s.left) || 0, d.clientWidth - el.offsetWidth));
      var y = Math.max(0, Math.min(parseFloat(s.top) || 0, d.clientHeight - el.offsetHeight));
      s.left = x + 'px';
      s.top = y + 'px';
    }
    var __timers = [];

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    __timers.push(setInterval(function () {
      __nudge("pet", mathRandomInt(-25, 25), mathRandomInt(-25, 25));
      __stay("pet");
    }, 200));

    __move("pet", 140, 200);
