  </style>
</head>
<body>
  <h2 id="title">숫자 맞히기 1~50</h2>
  <input id="g" type="number" placeholder="숫자 입력">
  <button id="ok">확인</button>
  <p id="msg"></p>
  <p id="best"></p>
  <script>
    var __mem = {};
    function __save(k, v) {
      k = 'ffb:' + k;
      __mem[k] = v;
      try { localStorage.setItem(k, JSON.stringify(v)); } catch (e) {}
    }
    function __load(k, d) {
      k = 'ffb:' + k;
      try {
        var s = localStorage.getItem(k);
        if (s !== null) return JSON.parse(s);
      } catch (e) {}
      return k in __mem ? __mem[k] : d;
    }

    var ans, tries;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    document.getElementById("ok").addEventListener('click', function () {
      tries = (typeof tries === 'number' ? tries : 0) + 1;
      if ((parseFloat(document.getElementById("g").value) || 0) < ans) {
        document.getElementById("msg").textContent = 'UP ⬆';
      } else if ((parseFloat(document.getElementById("g").value) || 0) > ans) {
        document.getElementById("msg").textContent = 'DOWN ⬇';
      } else {
        document.getElementById("msg").textContent = ['정답! ',tries,'번 만에 맞췄어요'].join('');
        if (__load('bestTry', 0) == 0 || tries < __load('bestTry', 0)) {
          __save('bestTry', tries);
          document.getElementById("best").textContent = '최고 기록: ' + String(tries);
        }
        ans = mathRandomInt(1, 50);
        tries = 0;
      }
    });

    ans = mathRandomInt(1, 50);
    tries = 0;
    document.getElementById("best").textContent = '최고 기록: ' + String(__load('bestTry', '없음'));
  </script>
</body>
</html>
