    body { font-family: sans-serif; text-align: center; background: #e0f2fe; color: #1f2937; padding: 24px; }
    button { font-size: 18px; padding: 10px 18px; margin: 4px; cursor: pointer; }
    input { font-size: 18px; padding: 8px; margin: 4px; }
  </style>
</head>
<body>
  <h1>상식 퀴즈</h1>
  <h2 id="question"></h2>
  <input id="answer" type="text">
  <button id="submit">제출</button>
  <p id="result"></p>
  <p id="score">점수: 0</p>
  <script>
    const quiz = [["태양계에서 가장 큰 행성은?","목성"],["1년은 몇 개월?","12"],["한글을 만든 왕은?","세종대왕"]];
    let index = 0;
    let score = 0;
    function ask() {
      document.getElementById('question').textContent = (index + 1) + '. ' + quiz[index][0];
      document.getElementById('answer').value = '';
    }
    document.getElementById('submit').addEventListener('click', function () {
      if (index >= quiz.length) return;
      const ok = document.getElementById('answer').value.trim() === quiz[index][1];
      if (ok) score += 1;
      document.getElementById('result').textContent = ok ? '정답! 🎉' : '틀렸어요. 정답: ' + quiz[index][1];
      document.getElementById('score').textContent = '점수: ' + score;
      index += 1;
      if (index < quiz.length) {
        ask();
      } else {
        document.getElementById('question').textContent = '끝! ' + quiz.length + '문제 중 ' + score + '개 맞혔어요';
      }
    });
    ask();
  </script>
</body>
</html>
