    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    var __cx = 0, __cy = 0;
    var __fol = {}, __folOn = false, __moved = false;
    document.addEventListener('pointermove', function () { __moved = true; });
    document.addEventListener('pointerdown', function () { __moved = true; });
    function __folLoop() {
      for (var n in __fol) {
        var el = document.getElementById(n);
        if (!el) { delete __fol[n]; continue; }
        if (!__moved) continue;
        var s = el.style, tx = __cx - el.offsetWidth / 2, ty = __cy - el.offsetHeight / 2;
        if (s.position !== 'absolute') {
          var r = el.getBoundingClientRect();
          s.position = 'absolute';
          s.left = (r.left + window.pageXOffset) + 'px';
          s.top = (r.top + window.pageYOffset) + 'px';
        }
        var x = parseFloat(s.left) || 0, y = parseFloat(s.top) || 0, k = __fol[n] === 'soft' ? 0.15 : 1;
        s.left = (x + (tx - x) * k) + 'px';
        s.top = (y + (ty - y) * k) + 'px';
        s.pointerEvents = 'none';
      }
      requestAnimationFrame(__folLoop);
    }
    function __follow(name, mode) {
      if (mode === 'stop') {
        delete __fol[name];
        var e = document.getElementById(name);
        if (e) e.style.pointerEvents = '';
        return;
      }
      $(name);
      __fol[name] = mode;
      document.body.style.touchAction = 'none';
