        score = (typeof score === 'number' ? score : 0) + 1;
        document.getElementById("점수판").textContent = ['점수: ',score,' / 5'].join('');
        __beep(261.63, 0.1);
        __move("별", mathRandomInt(20, 240), mathRandomInt(150, 300));
        if (score >= 5) {
          __timers.forEach(clearInterval);
          __show("별", "hide");
          alert('성공! ⭐ 5개를 모았어요 🎉');
        }
      }
    }, 50));
    document.addEventListener('keydown', function (e) {
      if (e.key === "ArrowLeft") {
        e.preventDefault();
        __nudge("로켓", -18, 0);
        __stay("로켓");
      }
    });
    document.addEventListener('keydown', function (e) {
      if (e.key === "ArrowRight") {
        e.preventDefault();
        __nudge("로켓", 18, 0);
        __stay("로켓");
      }
    });
    document.addEventListener('keydown', function (e) {
      if (e.key === "ArrowUp") {
        e.preventDefault();
        __nudge("로켓", 0, -18);
        __stay("로켓");
      }
    });
    document.addEventListener('keydown', function (e) {
      if (e.key === "ArrowDown") {
        e.preventDefault();
        __nudge("로켓", 0, 18);
        __stay("로켓");
      }
    });

    score = 0;
    __move("로켓", 40, 300);
    __move("별", 200, 200);
  </script>
</body>
</html>
