  </style>
</head>
<body>
  <h2 id="t">Click to draw dots</h2>
  <canvas id="pad" width="320" height="240"></canvas>
  <div id="r" class="box row">
    <input id="size" type="number" placeholder="Size (default 10)">
    <button id="clear">Clear</button>
  </div>
  <p id="count">Dots: 0</p>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    var __mx = 0, __my = 0;
    function __pos(e, el) {
      var r = el.getBoundingClientRect();
      __mx = Math.round((e.clientX - r.left) * (el.width ? el.width / r.width : 1));
      __my = Math.round((e.clientY - r.top) * (el.height ? el.height / r.height : 1));
    }
    function __pen(name) { return $(name).getContext('2d'); }
    function __clear(name) { var c = $(name); __pen(name).clearRect(0, 0, c.width, c.height); }
    function __circle(name, x, y, r, color) { var g = __pen(name); g.fillStyle = color; g.beginPath(); g.arc(x, y, Math.max(0, r), 0, Math.PI * 2); g.fill(); }

    var n;

    document.getElementById("pad").addEventListener('click', function (e) {
      __pos(e, this);
      __circle("pad", __mx, __my, (parseFloat(document.getElementById("size").value) || 0) > 0 ? (parseFloat(document.getElementById("size").value) || 0) : 10, 'hsl(' + Math.floor(Math.random() * 360) + ', 80%, 60%)');
      n = (typeof n === 'number' ? n : 0) + 1;
      document.getElementById("count").textContent = 'Dots: ' + String(n);
    });
    document.getElementById("clear").addEventListener('click', function () {
      __clear("pad");
      n = 0;
      document.getElementById("count").textContent = 'Dots: 0';
    });

    n = 0;
  </script>
</body>
