    body { margin: 0; padding: 24px; font-family: system-ui, "Apple SD Gothic Neo", "Noto Sans KR", sans-serif; line-height: 1.5; background: #ffffff; color: #1f2937; text-align: center; }
    button { font: inherit; font-weight: 700; padding: 10px 18px; margin: 4px; border: 0; border-radius: 10px; background: #ffc93c; color: #1c1405; cursor: pointer; }
    .box { display: flex; flex-direction: column; gap: 8px; padding: 12px; margin: 8px 0; border-radius: 12px; align-items: center; }
    .box.row { flex-direction: row; flex-wrap: wrap; align-items: center; justify-content: center; }
  </style>
</head>
<body>
  <h2 id="title">Reading Habit</h2>
  <div id="week" class="box row">
    <button id="d0">Mon ⬜</button>
    <button id="d1">Tue ⬜</button>
    <button id="d2">Wed ⬜</button>
    <button id="d3">Thu ⬜</button>
    <button id="d4">Fri ⬜</button>
  </div>
  <h3 id="count">Done this week: 0 days</h3>
  <h3 id="msg"></h3>
  <script>
    var __audio;
    function __beep(freq, sec) {
      __audio = __audio || new (window.AudioContext || window.webkitAudioContext)();
      var o = __audio.createOscillator(), g = __audio.createGain(), t = __audio.currentTime;
      o.frequency.value = freq;
      o.connect(g); g.connect(__audio.destination);
      g.gain.setValueAtTime(0.2, t);
      g.gain.exponentialRampToValueAtTime(0.001, t + sec);
      o.start(t); o.stop(t + sec);
    }

    var k, done, c, x;

    // 이 함수를 설명하세요...
    function tick(k) {
      done[(k - 1)] = !done[(k - 1)];
      c = 0;
      for (var x_index in done) {
        x = done[x_index];
        if (x) {
          c = (typeof c === 'number' ? c : 0) + 1;
        }
      }
      document.getElementById("count").textContent = ['Done this week: ',c,' days'].join('');
      if (c == 5) {
        document.getElementById("msg").textContent = '🔥 Perfect week!';
        __beep(523.25, 0.3);
      } else {
        document.getElementById("msg").textContent = '';
      }
    }

    function listsRepeat(value, n) {
      var array = [];
      for (var i = 0; i < n; i++) {
        array[i] = value;
      }
      return array;
    }

    document.getElementById("d0").addEventListener('click', function () {
      tick(1);
      document.getElementById("d0").textContent = done[0] ? 'Mon ✅' : 'Mon ⬜';
    });
    document.getElementById("d1").addEventListener('click', function () {
      tick(2);
      document.getElementById("d1").textContent = done[1] ? 'Tue ✅' : 'Tue ⬜';
    });
    document.getElementById("d2").addEventListener('click', function () {
      tick(3);
      document.getElementById("d2").textContent = done[2] ? 'Wed ✅' : 'Wed ⬜';
    });
    document.getElementById("d3").addEventListener('click', function () {
      tick(4);
      document.getElementById("d3").textContent = done[3] ? 'Thu ✅' : 'Thu ⬜';
    });
    document.getElementById("d4").addEventListener('click', function () {
      tick(5);
      document.getElementById("d4").textContent = done[4] ? 'Fri ✅' : 'Fri ⬜';
    });

    done = listsRepeat(false, 5);
  </script>
</body>
</html>
