    });
    document.addEventListener('keydown', function (e) {
      if (e.key === "ArrowUp") {
        e.preventDefault();
        __nudge("로켓", 0, -18);
        __stay("로켓");
      }
    });
    document.addEventListener('keydown', function (e) {
