<body>
  <h2 id="t">🔵 곱셈 그림</h2>
  <input id="w" type="number" placeholder="가로 (1~10)">
  <input id="hh" type="number" placeholder="세로 (1~8)">
  <button id="go">그리기</button>
  <canvas id="cv" width="300" height="200"></canvas>
  <h3 id="out"></h3>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __pen(name) { return $(name).getContext('2d'); }
    function __clear(name) { var c = $(name); __pen(name).clearRect(0, 0, c.width, c.height); }
    function __circle(name, x, y, r, color) { var g = __pen(name); g.fillStyle = color; g.beginPath(); g.arc(x, y, Math.max(0, r), 0, Math.PI * 2); g.fill(); }

    var w, r, i, j;

    document.getElementById("go").addEventListener('click', function () {
      __clear("cv");
      w = Math.min(Math.max((parseFloat(document.getElementById("w").value) || 0), 1), 10);
      r = Math.min(Math.max((parseFloat(document.getElementById("hh").value) || 0), 1), 8);
      var i_inc = 1;
      if (1 > r) {
        i_inc = -i_inc;
      }
      for (i = 1; i_inc >= 0 ? i <= r : i >= r; i += i_inc) {
        var j_inc = 1;
        if (1 > w) {
          j_inc = -j_inc;
        }
        for (j = 1; j_inc >= 0 ? j <= w : j >= w; j += j_inc) {
          __circle("cv", j * 28 - 10, i * 24 - 8, 9, '#3b82f6');
        }
      }
      document.getElementById("out").textContent = [w,' × ',r,' = ',w * r].join('');
    });
  </script>
</body>
</html>
