      for (i = 1; i_inc >= 0 ? i <= i_end : i >= i_end; i += i_inc) {
        if (t.charAt((i - 1)) == f) {
          cnt = (typeof cnt === 'number' ? cnt : 0) + 1;
        }
      }
      document.getElementById("out").textContent = ['"',f,'"은(는) ',cnt,'번 나와요'].join('');
    });
  </script>
