      secret = mathRandomInt(1000, 9999);
      document.getElementById("num").textContent = secret;
      __show("num", "show");
      document.getElementById("res").textContent = '';
      setTimeout(function () {
        __show("num", "hide");
      }, (3) * 1000);
    });
    document.getElementById("chk").addEventListener('click', function () {
      if ((parseFloat(document.getElementById("ans").value) || 0) == secret) {
