    <input id="nBox" type="number" placeholder="N">
    <button id="calcBtn">계산</button>
  </div>
  <h2 id="result"></h2>
  <script>
    var total, k;

    document.getElementById("calcBtn").addEventListener('click', function () {
      total = 0;
      var k_end = (parseFloat(document.getElementById("nBox").value) || 0);
      var k_inc = 1;
      if (1 > k_end) {
        k_inc = -k_inc;
