      for (k = 1; k_inc >= 0 ? k <= k_end : k >= k_end; k += k_inc) {
        total = (typeof total === 'number' ? total : 0) + k;
      }
      document.getElementById("result").textContent = '합계: ' + String(total);
    });
  </script>
</body>
</html>
