      run = !run;
    });
    document.getElementById("reset").addEventListener('click', function () {
      run = false;
      t = 0;
      document.getElementById("show").textContent = 0;
      document.getElementById("laps").textContent = '';
    });
    document.getElementById("lapB").addEventListener('click', function () {
      __add("laps", String(t / 10) + '초');
    });
    __timers.push(setInterval(function () {
      if (run) {
        t = (typeof t === 'number' ? t : 0) + 1;
        document.getElementById("show").textContent = t / 10;
