    .box.row { flex-direction: row; flex-wrap: wrap; align-items: center; justify-content: center; }
  </style>
</head>
<body>
  <h1 id="num">0</h1>
  <div id="bx" class="box row">
    <button id="minus">-1</button>
    <button id="plus">+1</button>
    <button id="zero">0으로</button>
  </div>
  <script>
    var __mem = {};
    function __save(k, v) {
      k = 'ffb:' + k;
      __mem[k] = v;
      try { localStorage.setItem(k, JSON.stringify(v)); } catch (e) {}
    }
    function __load(k, d) {
      k = 'ffb:' + k;
      try {
        var s = localStorage.getItem(k);
        if (s !== null) return JSON.parse(s);
      } catch (e) {}
      return k in __mem ? __mem[k] : d;
    }

    var count;

    // 이 함수를 설명하세요...
    function show() {
      document.getElementById("num").textContent = count;
      __save('count', count);
    }

    document.getElementById("plus").addEventListener('click', function () {
      count = (typeof count === 'number' ? count : 0) + 1;
      show();
    });
    document.getElementById("minus").addEventListener('click', function () {
      if (count > 0) {
        count = (typeof count === 'number' ? count : 0) + -1;
      }
      show();
    });
    document.getElementById("zero").addEventListener('click', function () {
      count = 0;
      show();
    });

    count = __load('count', 0);
    show();
  </script>
</body>
</html>
