    function factorial(k) {
      result = 1;
      var i_inc = 1;
      if (1 > k) {
        i_inc = -i_inc;
      }
      for (i = 1; i_inc >= 0 ? i <= k : i >= k; i += i_inc) {
        result = result * i;
      }
      return result;
    }

    document.getElementById("goBtn").addEventListener('click', function () {
      n = (parseFloat(document.getElementById("nBox").value) || 0);
      document.getElementById("out").textContent = [n,'! = ',factorial(n)].join('');
    });
  </script>
