  <h1 id="title">몬스터 배틀</h1>
  <h2 id="meTx">나 ❤️ 50</h2>
  <h2 id="monTx">몬스터 👾 50</h2>
  <div id="btns" class="box row">
    <button id="atkBtn">공격 ⚔️</button>
  </div>
  <h2 id="result"></h2>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __show(name, mode) {
      var el = $(name);
      if (mode === 'toggle') mode = el.style.display === 'none' ? 'show' : 'hide';
      el.style.display = mode === 'hide' ? 'none' : '';
    }

    var hp, mhp;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    // 이 함수를 설명하세요...
    function turn() {
      hp = (typeof hp === 'number' ? hp : 0) + -1 * mathRandomInt(2, 7);
      document.getElementById("meTx").textContent = '나 ❤️ ' + String(hp);
      document.getElementById("monTx").textContent = '몬스터 👾 ' + String(mhp);
      if (mhp <= 0) {
        document.getElementById("result").textContent = '몬스터를 물리쳤다! 🏆';
        __show("btns", "hide");
      } else if (hp <= 0) {
        document.getElementById("result").textContent = '쓰러졌다... 💀';
        __show("btns", "hide");
      }
    }

    document.getElementById("atkBtn").addEventListener('click', function () {
      mhp = (typeof mhp === 'number' ? mhp : 0) + -1 * mathRandomInt(3, 9);
      turn();
    });

    hp = 50;
    mhp = 50;
  </script>
</body>
</html>
