  <h2 id="t">🎨 그림판</h2>
  <div id="bx" class="box row">
    <button id="red">빨강</button>
    <button id="blue">파랑</button>
    <button id="green">초록</button>
    <button id="clr">지우기</button>
  </div>
  <canvas id="board" width="320" height="220"></canvas>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    var __mx = 0, __my = 0;
    function __pos(e, el) {
      var r = el.getBoundingClientRect();
      __mx = Math.round((e.clientX - r.left) * (el.width ? el.width / r.width : 1));
      __my = Math.round((e.clientY - r.top) * (el.height ? el.height / r.height : 1));
    }
    function __pen(name) { return $(name).getContext('2d'); }
    function __clear(name) { var c = $(name); __pen(name).clearRect(0, 0, c.width, c.height); }
    function __rect(name, x, y, w, h, color) { var g = __pen(name); g.fillStyle = color; g.fillRect(x, y, w, h); }
    function __circle(name, x, y, r, color) { var g = __pen(name); g.fillStyle = color; g.beginPath(); g.arc(x, y, Math.max(0, r), 0, Math.PI * 2); g.fill(); }

    var pen;

    document.getElementById("red").addEventListener('click', function () {
      pen = "#ef4444";
    });
    document.getElementById("blue").addEventListener('click', function () {
      pen = "#3b82f6";
    });
    document.getElementById("green").addEventListener('click', function () {
      pen = "#22c55e";
    });
    document.getElementById("clr").addEventListener('click', function () {
      __clear("board");
      __rect("board", 0, 0, 320, 220, "#ef4444");
    });
    document.getElementById("board").style.touchAction = 'none';
    document.getElementById("board").addEventListener('pointermove', function (e) {
      if (!e.buttons) return;
      __pos(e, this);
      __circle("board", __mx, __my, 4, pen);
    });

    pen = '#ef4444';
    __rect("board", 0, 0, 320, 220, "#ef4444");
  </script>
</body>
</html>
